-- 1. La tabla
create table public.notas (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  titulo text not null,
  contenido text,
  creada_en timestamptz not null default now()
);

-- 2. El candado. Esta línea es la que casi todo el mundo olvida.
alter table public.notas enable row level security;

-- 3. Las cuatro reglas: mirar, crear, cambiar, borrar.
create policy "cada uno ve sus notas"
  on public.notas for select
  to authenticated
  using ( auth.uid() = user_id );

create policy "cada uno crea sus notas"
  on public.notas for insert
  to authenticated
  with check ( auth.uid() = user_id );

create policy "cada uno cambia sus notas"
  on public.notas for update
  to authenticated
  using ( auth.uid() = user_id )
  with check ( auth.uid() = user_id );

create policy "cada uno borra sus notas"
  on public.notas for delete
  to authenticated
  using ( auth.uid() = user_id );

-- 4. Para que buscar por usuario no se arrastre cuando haya miles de filas.
create index notas_user_id_idx on public.notas (user_id);

# archivo: .env.local   (este archivo NO se sube a GitHub)
VITE_SUPABASE_URL=https://TU-PROYECTO.supabase.co
VITE_SUPABASE_ANON_KEY=PEGA_AQUI_LA_CLAVE_PUBLICA

// archivo: src/supabase.js
import { createClient } from '@supabase/supabase-js'

// La clave pública puede verse en el navegador: es su trabajo.
// Quien protege los datos son las políticas, no esta clave.
export const supabase = createClient(
  import.meta.env.VITE_SUPABASE_URL,
  import.meta.env.VITE_SUPABASE_ANON_KEY
)

// Leer las notas del usuario que ha iniciado sesión.
// Con las políticas puestas, no hace falta filtrar por user_id:
// la base de datos ya no le enseña las de nadie más.
const { data, error } = await supabase
  .from('notas')
  .select('id, titulo, contenido, creada_en')
  .order('creada_en', { ascending: false })

if (error) {
  console.log('Fallo de Supabase:', error.message)
} else if (data.length === 0) {
  console.log('Cero filas. O no hay datos, o falta la política de lectura.')
}
